    int students = 45;
    float height = 1.72f;
    double balance = 12500.75;
    char grade = 'A';

    printf("Students: %d\n", students);
    printf("Height: %.2f m\n", height);
    printf("Balance: KSh %.2f\n", balance);
    printf("Grade: %c\n", grade);
