    printf("[%d]\n", 42);          /* integer */
    printf("[%5d]\n", 42);         /* width 5, right-aligned */
    printf("[%-5d]\n", 42);        /* left-aligned */
    printf("[%05d]\n", 42);        /* padded with zeros */
    printf("[%.2f]\n", 3.14159);   /* 2 decimal places */
